    "coreAnswer": "Tiền phạt vi phạm xuất nhập cảnh (범칙금) là khoản tiền tương đương tiền phạt hình sự do cơ quan xuất nhập cảnh thông báo đối với hành vi vi phạm Luật Quản lý xuất nhập cảnh; tiền phạt hành chính (과태료) là chế tài hành chính áp dụng cho các vi phạm như nghĩa vụ khai báo, đăng ký; còn hình phạt tiền (벌금형) là hình phạt do tòa án quyết định, vì vậy cơ sở áp dụng và ảnh hưởng về sau của chúng khác nhau. Tiền phạt vi phạm phải nộp trong vòng 15 ngày kể từ ngày nhận giấy thông báo; nếu nộp đúng như thông báo thì sẽ không bị xử phạt lại vì cùng vụ việc, nhưng hồ sơ nộp phạt có thể được kiểm tra khi thẩm tra cấp phép lưu trú. Văn phòng chúng tôi (선샤인행정사사무소) cung cấp dịch vụ hỗ trợ soạn hồ sơ giải trình xin giảm tiền phạt vi phạm và nộp thay đơn xin gia hạn thời gian lưu trú sau khi nộp phạt.",
