        "a": "Tiền phạt hành chính cũng có khả năng được miễn. Bộ trưởng Bộ Tư pháp có thể miễn tiền phạt hành chính do vi phạm Luật Quản lý xuất nhập cảnh khi xét các tình tiết như tuổi tác và môi trường sống, động cơ và hậu quả vi phạm, khả năng chi trả tiền phạt hành chính. Hãy chuẩn bị tài liệu cho thấy lý do khai báo bị trễ (nằm viện, đi công tác…) và bản tường trình hoàn cảnh để giải trình. Tiền phạt hành chính không phải là xử phạt hình sự mà là chế tài hành chính, nhưng thông tin nộp phạt có thể được kiểm tra khi thẩm tra cấp phép lưu trú, vì vậy đừng để quá thời hạn nộp ghi trên giấy báo."
