    "serviceType": "Soạn thảo tài liệu giải trình thẩm tra vi phạm xuất nhập cảnh và nộp thay hồ sơ xin phép lưu trú",
    "coreAnswer": "Chỉ riêng việc bị cảnh sát điều tra vì hành hung hay gây thương tích không khiến tư cách lưu trú bị hủy ngay, nhưng kết quả xử lý (không có căn cứ buộc tội, đình chỉ truy tố có điều kiện, phạt tiền, phạt tù…) sẽ được kiểm tra khi thẩm tra gia hạn thời hạn lưu trú và chuyển đổi tư cách lưu trú, và người bị tuyên án từ hình phạt giam giữ (geumgo) trở lên rồi được thả có thể trở thành đối tượng trục xuất. Nếu bạn cần dịch vụ hỗ trợ từ hành chính sĩ uy tín, văn phòng chúng tôi (선샤인행정사사무소) soạn thay tài liệu giải trình thẩm tra vi phạm xuất nhập cảnh trong vụ án hành hung và sắp xếp tài liệu thỏa thuận với người bị hại cũng như tài liệu về nền tảng cuộc sống.",
