        "a": "Người tuyển dụng người nước ngoài không có tư cách lưu trú được phép lao động có thể bị phạt tù đến 3 năm hoặc phạt tiền đến 30 triệu won theo Luật Quản lý xuất nhập cảnh; nếu nhân viên tuyển dụng trong khi thực hiện công việc thì pháp nhân hoặc cá nhân chủ doanh nghiệp cũng có thể bị phạt tiền kèm theo (trừ trường hợp đã không lơ là sự chú ý và giám sát cần thiết). Khi điều tra xác nhận có vi phạm, cơ quan xuất nhập cảnh và người nước ngoài có thể thông báo tiền phạt vi phạm; nếu nộp trong vòng 15 ngày kể từ ngày nhận giấy thông báo thì sẽ không bị xử phạt lại cho cùng vụ việc, còn nếu không nộp sẽ bị chuyển tố giác. Nếu tình tiết vi phạm được xác định tương đương mức hình phạt giam giữ trở lên thì sẽ bị chuyển tố giác ngay mà không qua thông báo. Khi bị điều tra, hãy chuẩn bị hợp đồng lao động, chứng từ trả lương và hồ sơ đã xác nhận tư cách lưu trú khi tuyển dụng."
