        "a": "Trong một thời gian nhất định có thể không được cấp Giấy xác nhận cấp visa. Nếu bị phạt tiền hoặc tiền phạt vi phạm từ 5 triệu won trở lên vì tuyển dụng bất hợp pháp và đã nộp thì trong 3 năm kể từ ngày nộp, nếu dưới 5 triệu won thì trong 1 năm, người mời có thể không được cấp Giấy xác nhận cấp visa; nếu bị án thực từ hình phạt giam giữ trở lên hoặc án treo thì áp dụng mốc 3 năm. Thời gian này có thể được ấn định ngắn hơn khi xét đến nguy cơ tái phạm, động cơ và hậu quả vi phạm… Tại doanh nghiệp bị hạn chế cấp visa do từng bị xử phạt vì tuyển dụng bất hợp pháp…, du học sinh cũng không được phép làm thêm bán thời gian."
