        "a": "Đó là làm việc khi không có tư cách lưu trú được phép lao động, nên có thể bị phạt tù đến 3 năm hoặc phạt tiền đến 30 triệu won và thuộc diện bị trục xuất. Tùy kết quả điều tra, bạn có thể bị thông báo xử phạt tiền phạt vi phạm rồi tự xuất cảnh theo lệnh xuất cảnh, hoặc bị ra lệnh trục xuất. Người muốn tự xuất cảnh bằng chi phí của mình có thể thuộc diện lệnh xuất cảnh, vì vậy hãy chuẩn bị hộ chiếu, đặt chỗ vé máy bay về nước, giấy tờ về nơi lưu trú và thông tin liên lạc. Nếu nhận lệnh trục xuất và xuất cảnh thì có thể bị cấm nhập cảnh trong thời gian chưa qua 5 năm."
