        "a": "Đây là công việc không thuộc diện được cấp phép nên có thể bị coi là lao động bất hợp pháp. Trong chế độ làm thêm bán thời gian của du học sinh, các hoạt động của người lao động hình thức đặc thù như tài xế chuyển phát, tài xế công ty dịch vụ giao hàng, nhân viên tư vấn bảo hiểm được quy định là lĩnh vực bị hạn chế. Nếu làm hoạt động thuộc tư cách lưu trú khác mà không có giấy phép thì có thể bị phạt tù đến 3 năm hoặc phạt tiền đến 30 triệu won; nếu mức vi phạm nhẹ thì có thể bị khuyến cáo xuất cảnh, nếu không thì có thể thuộc diện bị trục xuất. Nếu đã làm rồi, hãy sắp xếp thời gian làm việc, thu nhập, giấy xác nhận đang học và bảng điểm để giải trình hoàn cảnh, và xem xét hướng xin mới giấy phép làm thêm bán thời gian trong lĩnh vực được phép."
