        "a": "Nộp tiền phạt vi phạm không có nghĩa là được bảo đảm tiếp tục lưu trú. Nếu sau khi thông báo xử phạt thấy cần áp dụng biện pháp xuất cảnh thì bạn có thể nhận lệnh xuất cảnh, và dù tiếp tục lưu trú thì lịch sử tiền phạt vi phạm vẫn được xem xét khi thẩm định gia hạn, chuyển đổi sau này. Ví dụ, tư cách tìm việc (D-10) bị hạn chế nếu tiền phạt vi phạm lần đầu từ 5 triệu won trở lên hoặc tái phạm với tổng cộng trong 3 năm gần đây từ 7 triệu won trở lên; kiều bào (F-4) nếu tổng tiền phạt vi phạm từ 7 triệu won trở lên thì bị hạn chế 3 năm kể từ ngày nộp đủ tiền phạt tại thời điểm đó (được giảm còn 1 năm nếu xác nhận đã làm tình nguyện từ 100 giờ trở lên trong khoảng từ 6 tháng trở lên). Hãy lưu giữ biên lai nộp tiền phạt vi phạm, bản tường trình sự việc vi phạm và giấy tờ chứng minh việc làm hợp pháp hiện tại."
