        "a": "Đó là làm việc ở nơi không phải nơi làm việc được chỉ định, nên có thể bị phạt tù đến 1 năm hoặc phạt tiền đến 10 triệu won và cũng có thể thuộc diện bị trục xuất. Chủ doanh nghiệp giao việc đó cũng bị xử phạt vì đã tuyển dụng người nước ngoài chưa có giấy phép thay đổi, bổ sung nơi làm việc. Khi bị điều tra, hãy khai trung thực về thời gian làm việc, tiền lương đã nhận, tình hình làm việc tại nơi làm việc gốc và chuẩn bị giấy xác nhận đang làm việc của nơi làm việc gốc. Nếu bị thông báo xử phạt tiền phạt vi phạm thì phải nộp trong vòng 15 ngày kể từ ngày nhận giấy thông báo."
