        "q": "Tôi phát hiện muộn là đã quá hạn lưu trú ở Hàn Quốc, nếu tự đến cục xuất nhập cảnh trước thì sẽ phải làm những thủ tục gì?",
        "a": "Cơ quan xuất nhập cảnh có thẩm quyền sẽ điều tra hành vi vi phạm, sau đó ra thông báo nộp tiền phạt vi phạm, và nếu thấy cần buộc xuất cảnh thì đồng thời ra lệnh xuất cảnh. Khi nhận giấy thông báo, bạn phải nộp tiền phạt trong vòng 15 ngày kể từ ngày nhận; nếu nộp đúng như thông báo thì sẽ không bị xử phạt lại cho cùng vụ việc. Khi đến trình diện, hãy mang theo hộ chiếu, thẻ đăng ký người nước ngoài và tài liệu chứng minh lý do quá hạn (giấy chẩn đoán, xác nhận chuyến bay bị hủy…). Nếu nhận lệnh xuất cảnh, bạn phải xuất cảnh trước thời hạn ghi trong lệnh xuất cảnh."
