        "a": "Hoàn cảnh sẽ được cân nhắc khi quyết định xử lý. Tiền phạt vi phạm có thể được giảm trong phạm vi một nửa mức chuẩn, có xét đến tuổi tác và hoàn cảnh, động cơ và hậu quả vi phạm, khả năng chi trả, số lần vi phạm…; Bộ trưởng Bộ Tư pháp cũng có thể miễn hẳn việc thông báo nộp phạt khi xét đến tình tiết. Hãy chuẩn bị các tài liệu cho thấy khoảng thời gian và lý do không thể nộp đơn khớp với nhau, như giấy xác nhận nhập viện, giấy chẩn đoán, hóa đơn viện phí. Tốt nhất nên nộp tài liệu cho cơ quan ngay khi biết mình đã vi phạm."
