        "a": "Bạn phải xuất cảnh trước thời hạn ghi trong giấy thông báo từ chối; thời hạn này được ấn định trong phạm vi không quá 14 ngày kể từ ngày cấp giấy thông báo, hoặc có thể là ngày hết hạn lưu trú hiện tại. Nếu quá thời hạn này, bạn sẽ vi phạm quá hạn lưu trú. Nếu không thể xuất cảnh đúng hạn vì bệnh tật hoặc vấn đề phương tiện đi lại, bạn có thể xin hoãn thời hạn xuất cảnh; nếu có khả năng chuyển sang tư cách lưu trú khác thì cần xem xét trước khi hết hạn. Trước tiên, hãy xác định lý do bị từ chối để đánh giá xem đó có phải là vấn đề có thể bổ sung được không."
