        "a": "Thời hạn xuất cảnh được ấn định trong phạm vi 30 ngày kể từ ngày ban hành lệnh xuất cảnh, và có thể kèm điều kiện như hạn chế nơi ở. Khi thấy cần thiết, cơ quan có thể yêu cầu ký quỹ tiền bảo đảm thực hiện đến 20 triệu won, có xét đến lý do và động cơ của lệnh xuất cảnh, tiền sử vi phạm, tuổi tác, hoàn cảnh, tài sản, nguy cơ bỏ trốn và lý do nhân đạo. Nếu không xuất cảnh trước thời hạn hoặc vi phạm điều kiện, lệnh trục xuất sẽ được ban hành ngay và tiền bảo đảm có thể bị sung vào ngân sách nhà nước. Hãy lưu giữ thông tin đặt vé máy bay và lệnh xuất cảnh; nếu phát sinh lý do bất khả kháng, hãy xin hoãn trước khi hết hạn."
