        "a": "Điều này tùy thuộc vào việc bạn xuất cảnh theo thủ tục nào. Nếu xuất cảnh theo lệnh trục xuất, bạn có thể bị cấm nhập cảnh trong thời gian chưa đủ 5 năm; còn nếu nhận lệnh xuất cảnh và xuất cảnh đúng thời hạn thì không trực tiếp rơi vào lý do cấm nhập cảnh theo luật này. Tuy nhiên, việc có bị hạn chế nhập cảnh hay không và thời gian bao lâu có thể được quyết định riêng theo từng trường hợp, và lịch sử lưu trú cũng sẽ được kiểm tra khi xét visa sau này. Hãy giữ biên lai nộp tiền phạt vi phạm và lệnh xuất cảnh, vì đây sẽ là tài liệu khi đề nghị gỡ bỏ hạn chế nhập cảnh sau này."
