        "a": "Đây là một vi phạm khác. Người nước ngoài muốn lưu trú quá 90 ngày phải đăng ký người nước ngoài trong vòng 90 ngày kể từ ngày nhập cảnh; nếu vi phạm có thể bị phạt tù đến 1 năm hoặc phạt tiền đến 10 triệu won, đồng thời thuộc lý do bị trục xuất. Nếu thời hạn lưu trú vẫn còn thì không phải là quá hạn lưu trú, nhưng việc đăng ký muộn có thể dẫn đến bị xử lý vi phạm. Hãy chuẩn bị hộ chiếu, ảnh, giấy tờ chứng minh nơi cư trú và tài liệu giải thích lý do chậm trễ rồi nộp đơn đăng ký ngay."
