        "a": "Nếu quá hạn, con bạn có thể bị coi là lưu trú mà không có tư cách lưu trú. Người nước ngoài sinh ra tại Hàn Quốc phải được cấp tư cách lưu trú trong vòng 90 ngày kể từ ngày sinh; nếu vi phạm mà vẫn lưu trú thì có thể bị phạt tù đến 3 năm hoặc phạt tiền đến 30 triệu won và cũng thuộc lý do bị trục xuất. Hãy chuẩn bị giấy chứng sinh, hộ chiếu và thẻ đăng ký người nước ngoài của cha mẹ, giấy tờ xác nhận quan hệ gia đình và nộp đơn trong thời hạn. Nếu đã quá hạn, tốt nhất nên nộp đơn ngay kèm tài liệu giải thích lý do chậm trễ."
