        "a": "Người bảo lãnh hoặc người liên quan có thể nộp đơn xin tạm thời giải trừ tạm giữ lên Ủy ban Tạm giữ Người nước ngoài; nếu được chấp thuận sẽ kèm điều kiện ký quỹ đến 20 triệu won, hạn chế nơi ở và báo cáo định kỳ. Nếu đã nhận lệnh trục xuất thì có thể khiếu nại trong vòng 7 ngày kể từ ngày nhận lệnh, vì vậy hãy kiểm tra thời hạn trước tiên. Hãy chuẩn bị giấy bảo lãnh nhân thân, giấy tờ quan hệ gia đình, giấy tờ xác nhận nơi cư trú và tài liệu về lý do cần giải trừ tạm thời như bệnh tật hay nuôi con nhỏ. Nếu không có hộ chiếu hoặc chưa có phương tiện đi lại thì việc hồi hương sẽ chậm và thời gian tạm giữ có thể kéo dài, nên hãy kiểm tra cả tình trạng hộ chiếu."
