        "a": "Lệnh xuất cảnh (출국명령) là quyết định yêu cầu chính người đó tự rời khỏi Hàn Quốc trước thời hạn đã định, còn trục xuất (강제퇴거) là việc công chức quản lý xuất nhập cảnh thi hành lệnh để đưa người đó về nước nhận. Người nhận lệnh trục xuất có thể bị tạm giữ (보호) tại cơ sở tạm giữ nếu không có hộ chiếu hoặc chưa có phương tiện đi lại nên không thể đưa về ngay, còn lệnh xuất cảnh là cơ chế tự rời đi trước thời hạn. Lệnh xuất cảnh được áp dụng cho người thuộc diện trục xuất nhưng muốn tự nguyện xuất cảnh bằng chi phí của mình, còn chi phí đưa về nước khi trục xuất thì người đứng đầu cơ quan có thể chi trả trong phạm vi ngân sách khi cần. Một điểm khác nữa là người đã xuất cảnh theo lệnh trục xuất mà chưa quá 5 năm được luật ghi rõ là đối tượng bị cấm nhập cảnh."
