        "a": "Bạn vẫn có thể nộp đơn; khi xét thị thực, cơ quan sẽ kiểm tra cả tiêu chuẩn xét chung bao gồm việc có bị hạn chế nhập cảnh hay không và tiêu chuẩn riêng của từng tư cách lưu trú. Quy định 5 năm sau khi bị trục xuất được ghi trong luật là lý do cấm nhập cảnh không áp dụng cho khuyến cáo xuất cảnh, nhưng cần kiểm tra riêng xem Bộ trưởng Bộ Tư pháp có cấm nhập cảnh vì lý do khác hay không. Khi nộp lại, hãy chuẩn bị bản sao giấy khuyến cáo xuất cảnh, hồ sơ cho thấy đã xuất cảnh trong thời hạn và giấy tờ thể hiện mục đích nhập cảnh lần này. Luật không quy định thời gian chờ chung trước khi được nộp lại."
