        "a": "Luật Quản lý Xuất nhập cảnh không quy định riêng thời hạn hay mẫu đơn cho việc 'xin gỡ bỏ' lệnh cấm nhập cảnh; cơ chế là Bộ trưởng Bộ Tư pháp quyết định cấm và gỡ bỏ. Nếu bị cấm theo yêu cầu của cơ quan hành chính khác, cơ quan đó phải đề nghị Bộ trưởng Bộ Tư pháp gỡ bỏ khi lý do không còn, nên điểm xuất phát là nộp tài liệu chứng minh lý do đã không còn cho cơ quan đó; còn nếu là lý do do Bộ Tư pháp trực tiếp đánh giá thì hãy hỏi Cơ quan Xuất nhập cảnh và Người nước ngoài có thẩm quyền hoặc cơ quan đại diện ngoại giao nơi bạn sẽ xin thị thực về nơi nộp hồ sơ. Hãy chuẩn bị bản trình bày lý do đề nghị gỡ bỏ, tài liệu cho thấy lý do cấm đã không còn và tài liệu về thay đổi hoàn cảnh như quan hệ gia đình. Luật không quy định thời gian xử lý, nên nếu lịch trình gấp thì cũng cần ghi rõ điều đó trong bản trình bày lý do."
