        "a": "Khi đã quá 5 năm, bạn không còn thuộc lý do 'chưa quá 5 năm kể từ khi xuất cảnh theo lệnh trục xuất', nhưng chỉ điều đó thì chưa bảo đảm được nhập cảnh. Bộ trưởng Bộ Tư pháp vẫn có thể cấm nhập cảnh vì lý do khác như lo ngại gây hại cho an toàn công cộng hoặc trật tự xã hội, và khi xét thị thực, cơ quan sẽ xem riêng mục đích nhập cảnh và tiêu chuẩn của từng tư cách lưu trú. Khi xin thị thực, hãy chuẩn bị hồ sơ xuất nhập cảnh cho thấy ngày xuất cảnh khi bị trục xuất và tài liệu về cuộc sống, nghề nghiệp sau đó. 5 năm được tính từ ngày xuất cảnh, nên cần xác định ngày xuất cảnh trước."
