        "a": "Khi kiểm tra nhập cảnh, cơ quan xem xét hiệu lực của hộ chiếu và thị thực, sự phù hợp giữa mục đích nhập cảnh và tư cách lưu trú, việc có thuộc diện cấm hoặc từ chối nhập cảnh hay không…, nên nguyên nhân có thể là do bị cấm nhập cảnh, nhưng cũng có thể là do không chứng minh được mục đích nhập cảnh. Khi không cho phép nhập cảnh, cơ quan sẽ đưa thông báo không cho phép nhập cảnh (입국 불허가 통지서), vì vậy hãy kiểm tra nội dung ghi trên giấy đó trước. Trước lần nhập cảnh tiếp theo, hãy chuẩn bị thông báo đó cùng các tài liệu thể hiện mục đích nhập cảnh như lịch trình du lịch, chỗ ở, vé máy bay về nước; nếu nghi ngờ bị cấm nhập cảnh, hãy cân nhắc cách xác nhận bằng việc xin thị thực tại cơ quan đại diện ngoại giao. Luật không quy định khi nào được thử nhập cảnh lại."
